logotype.css_complete:
/* ── UNRLVL Logotype v1.5 — chevron leading, studio en minúscula, movimiento reducido — copy this block exactly ── */
@keyframes prompt-blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
.lt-logotype {
  font-family: 'Bebas Neue', sans-serif;
  letter-spacing: 0.04em;
  line-height: 1;
  white-space: nowrap;
}
.lt-un {
  color: #F2F0EC;
}
.lt-chevron {
  color: #00FFD1;
  animation: prompt-blink 1.1s step-end infinite;
  display: inline-block;
  transform: scaleY(1.45) scaleX(0.72);
  transform-origin: center;
  letter-spacing: 0;
  margin-right: 0.02em;
}
.lt-studio {
  color: rgba(242,240,236,0.32);
  font-size: 0.72em;
  letter-spacing: 0.14em;
  margin-left: 0.18em;
  vertical-align: baseline;
}
/* Sizes */
.lt-logotype.size-nav    { font-size: 20px; }
.lt-logotype.size-footer { font-size: 28px; }
.lt-logotype.size-inline { font-size: 16px; }
/* Movimiento reducido: el chevron deja de parpadear para quien lo pidió a nivel de
   sistema. Va DENTRO de este bloque a propósito — el campo ordena copiarlo tal cual,
   así que una regla que viviera fuera se omitiría en cada implementación. */
@media (prefers-reduced-motion: reduce) {
  .lt-chevron { animation: none; }
}
